# Let's analyze the differences between inputs and outputs
inputs = ['gkjujw', 'yk', 'gubw', 'abax', 'eek']
outputs = ['gkjujw', 'yk', 'gubw', 'hkdax', 'eek']

print("Input -> Output:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"'{inp}' -> '{out}'")

print("\nAnalyzing differences:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"'{inp}' vs '{out}':")
        # Find differing positions
        for j, (char_in, char_out) in enumerate(zip(inp, out)):
            if char_in != char_out:
                print(f"  Position {j}: '{char_in}' -> '{char_out}'")
        # Also check lengths
        if len(inp) != len(out):
            print(f"  Length changed: {len(inp)} -> {len(out)}")

